scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_oncellclick = function(row, col) {
    var rrowIdx = dataList1.getRealRowIndex(row);
    console.log('gridview getFocusedRowIndex');
    console.log(grid1.getFocusedRowIndex());
    console.log('getCellData >> focusedRowIndex : ' + dataList1.getCellData(grid1.getFocusedRowIndex(), col));
    console.log('getRowJSON >> focusedRowIndex : ');
    console.log(dataList1.getRowJSON(grid1.getFocusedRowIndex()));
    //alert("getFocusedRowIndex" + " : " + grid1.getFocusedRowIndex() + "  , " + "focusedRowIndex" + " : " + dataList1.getCellData(grid1.getFocusedRowIndex(), col));
    log = "getFocusedRowIndex" + " : " + grid1.getFocusedRowIndex() + "  , " + "focusedRowIndex" + " : " + dataList1.getCellData(grid1.getFocusedRowIndex(), col);
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.trigger2_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header4', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkVal = function() {
    return log == 'getFocusedRowIndex : 1  , focusedRowIndex : 2';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. '금액'항목을 groupby 시킨다.
    //1. Group the item 'Amount'.
    //Verify step 1. The 'Amount' item is groupby.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '금액'항목의 '2'값을 클릭하여 알림창 또는 콘솔에서 index값을 확인한다.
    //2. Click the '2' value in the 'Amount' field to see the index value in the notification window or console.
    //Verify step 2. getFocusedRowIndex: 1, focusedRowIndex: 2
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_4_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "log == 'getFocusedRowIndex : 1  , focusedRowIndex : 2'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = "";
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 29-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
